from pathlib import Path
import re
import sys
p=Path(sys.argv[1] if len(sys.argv)>1 else 'index.html')
s=p.read_text(encoding='utf-8')
extra_css = r'''
body.auth-locked{overflow:hidden;background:#f4f7fa}body.auth-locked>.sidebar,body.auth-locked>main,body.auth-locked>.shade{display:none!important}.login-screen{position:fixed;inset:0;z-index:1000;display:none;align-items:center;justify-content:center;padding:calc(env(safe-area-inset-top) + 24px) 22px calc(env(safe-area-inset-bottom) + 24px);background:linear-gradient(145deg,#eef4f8 0%,#f9faf8 52%,#eef2e8 100%)}body.auth-locked .login-screen{display:flex}.login-shell{width:min(100%,430px);background:#fff;border:1px solid #dfe7ec;border-radius:28px;padding:34px 30px 30px;box-shadow:0 24px 70px rgba(8,56,89,.12)}.login-brand{display:flex;align-items:center;gap:14px;margin-bottom:26px}.login-brand img{width:66px;height:66px;border-radius:50%;object-fit:cover;border:1px solid #e1e8eb;background:#fff}.login-brand strong{display:block;font:800 25px 'Manrope',system-ui;letter-spacing:-.8px;color:#083859}.login-brand span{display:block;margin-top:2px;font-size:9px;letter-spacing:2.1px;color:#16879a;font-weight:700}.login-shell .eyebrow{margin-bottom:8px}.login-shell h1{font-size:27px;margin-bottom:8px}.login-copy{color:#73818a;font-size:12px;margin:0 0 24px;line-height:1.65}.login-field{margin-top:15px}.login-field label{display:block;font-size:11px;font-weight:700;color:#526875;margin-bottom:7px}.login-field input{width:100%;height:48px;border:1px solid #d8e2e8;border-radius:12px;padding:0 14px;background:#fbfcfd;color:#0b3555}.login-field input:focus{border-color:#18869a;box-shadow:0 0 0 3px rgba(24,134,154,.10)}.login-submit{width:100%;margin-top:22px;min-height:48px;border-radius:12px}.login-error{min-height:18px;margin:11px 0 0;color:#a44942;font-size:11px;text-align:center}.login-foot{margin:20px 0 0;text-align:center;color:#8b989f;font-size:10px}@media(max-width:850px){.topbar{height:auto;min-height:calc(72px + env(safe-area-inset-top));padding:calc(env(safe-area-inset-top) + 12px) 19px 10px}.mobile-menu{min-width:42px;min-height:42px;font-size:24px}.sidebar{padding-top:max(34px,calc(env(safe-area-inset-top) + 20px))}.menu-close{top:max(14px,env(safe-area-inset-top))}}@media(max-width:600px){.topbar{padding:calc(env(safe-area-inset-top) + 12px) 12px 10px}.login-shell{padding:29px 22px 25px;border-radius:23px}.login-brand img{width:60px;height:60px}.login-shell h1{font-size:24px}}
'''
assert '</style>' in s
s=s.replace('</style>',extra_css+'\n</style>',1)
login_html='''\n<div class="login-screen" id="loginScreen" role="dialog" aria-modal="true" aria-labelledby="loginTitle"><form class="login-shell" id="loginForm"><div class="login-brand"><img id="loginLogo" alt="Florindo Sistemas"><div><strong>Florindo</strong><span>SISTEMAS</span></div></div><p class="eyebrow">ACESSO RESTRITO</p><h1 id="loginTitle">Bem-vindo.</h1><p class="login-copy">Entre com seu usuário e senha para acessar clientes, sistemas, contratos e financeiro.</p><div class="login-field"><label for="loginUsername">Usuário</label><input id="loginUsername" name="username" type="text" inputmode="numeric" autocomplete="username" required></div><div class="login-field"><label for="loginPassword">Senha</label><input id="loginPassword" name="password" type="password" autocomplete="current-password" required></div><button class="button primary login-submit" id="loginButton" type="submit">Entrar</button><p class="login-error" id="loginError" role="alert"></p><p class="login-foot">Florindo Sistemas · acesso protegido</p></form></div>\n'''
s=s.replace('<body>','<body class="auth-locked">'+login_html,1)
s=s.replace("const NEON_TOKEN_KEY='florindo-neon-sync-key-v1';","const NEON_TOKEN_KEY='florindo-neon-sync-key-v1';\nconst LOGIN_USER_KEY='florindo-login-user-v1';",1)
needle="function setNeonToken(value){if(value)localStorage.setItem(NEON_TOKEN_KEY,value);else localStorage.removeItem(NEON_TOKEN_KEY)}"
helpers=r'''function setNeonToken(value){if(value)localStorage.setItem(NEON_TOKEN_KEY,value);else localStorage.removeItem(NEON_TOKEN_KEY)}
function showLogin(message=''){document.body.classList.add('auth-locked');const error=$('loginError');if(error)error.textContent=message;const saved=localStorage.getItem(LOGIN_USER_KEY)||'';if($('loginUsername')&&!$('loginUsername').value)$('loginUsername').value=saved;setTimeout(()=>$(saved?'loginPassword':'loginUsername')?.focus(),80)}
function hideLogin(){document.body.classList.remove('auth-locked');if($('loginError'))$('loginError').textContent='';if($('loginPassword'))$('loginPassword').value=''}
async function appLogin(username,password){const result=await neonRPC('florindo_login',{p_username:String(username||'').trim(),p_password:String(password||'')});if(!result?.token)throw Error('Não foi possível iniciar a sessão.');localStorage.setItem(LOGIN_USER_KEY,String(username||'').trim());setNeonToken(result.token);await connectNeon(result.token);hideLogin();return true}
async function appLogout(){const token=neonToken();try{if(token)await neonRPC('florindo_logout',{p_token:token})}catch{}setNeonToken('');neonOnline=false;updateSaveStatus();showLogin()}'''
assert needle in s
s=s.replace(needle,helpers,1)
old=""" if(neonToken()){\n  try{await connectNeon(neonToken())}catch(e){neonOnline=false;console.warn('Neon indisponível:',e);if(e.status===401||e.status===403||String(e.message).toLowerCase().includes('unauthorized')){setNeonToken('');toast('A chave do Neon não foi aceita. Conecte novamente em Meu espaço.')}}\n }\n updateSaveStatus();"""
assert old in s
s=s.replace(old," updateSaveStatus();",1)
s=s.replace("function updateSaveStatus(){let label;if(neonOnline)label='Sincronizado com Neon';else if(neonToken())label='Salvo local · Neon offline';else label=storageMode==='unavailable'?'Armazenamento indisponível':'Dados neste aparelho';$('saveStatus').textContent=label}","function updateSaveStatus(){let label;if(neonOnline)label='Sincronizado com Neon';else if(neonToken())label='Salvo local · sincronização offline';else label=storageMode==='unavailable'?'Armazenamento indisponível':'Sessão desconectada';$('saveStatus').textContent=label}",1)
s=s.replace("if(syncError)toast(neonToken()?'Alteração salva neste aparelho. A sincronização com o Neon será tentada novamente depois.':'Alteração salva neste aparelho. Reconecte o Neon em Meu espaço.');","if(syncError){if(!neonToken())showLogin('Sua sessão expirou. Entre novamente.');toast(neonToken()?'Alteração salva neste aparelho. A sincronização será tentada novamente depois.':'Alteração salva neste aparelho. Entre novamente para sincronizar.');}",1)
start=s.index('function settingsPage(){');end=s.index('\nfunction render(){',start)
new_settings=r'''function settingsPage(){const sessionLabel=neonOnline?'Conectado e sincronizado':neonToken()?'Sessão ativa · sem conexão':'Sessão desconectada';const loginUser=localStorage.getItem(LOGIN_USER_KEY)||'Usuário';return header('Seu espaço, do seu jeito.','Personalize sua central e mantenha uma cópia dos seus registros.')+`<div class="settings-grid"><section class="panel"><div class="panel-heading"><h2>Identidade do espaço</h2></div><form id="settingsForm"><div class="field"><label for="spaceName">Nome do espaço</label><input id="spaceName" name="name" maxlength="50" required value="${esc(state.settings.name)}"></div><div class="field" style="margin-top:17px"><label for="ownerName">Como você quer ser chamado?</label><input id="ownerName" name="owner" maxlength="100" value="${esc(state.settings.owner)}" placeholder="Seu primeiro nome"></div><button class="button primary" style="margin-top:20px">Salvar preferências</button></form></section><section class="panel"><div class="panel-heading"><h2>Backup & seus dados</h2></div><div class="notice">Clientes, sistemas, atualizações, contratos e financeiro são sincronizados com o Neon. Tarefas, preferências e os arquivos anexados aos contratos continuam com uma cópia local neste aparelho.</div><div class="settings-actions">${action('export','↓ Exportar backup','','','button')}${action('import','↑ Importar backup','','','button')}</div><p class="helper" style="margin-top:15px">O backup continua incluindo clientes, sistemas, atualizações, contratos, financeiro, tarefas e anexos locais.</p></section><section class="panel"><div class="panel-heading"><h2>Como organizar</h2></div><p class="subtext">Comece pelos clientes. Cadastre os sistemas de cada um. Registre versões e mudanças em Atualizações, guarde documentos em Contratos e organize os próximos passos em Minha rotina.</p><p class="subtext" style="margin-top:13px">As exclusões sincronizadas são arquivadas no banco para preservar o histórico.</p></section><section class="panel"><div class="panel-heading"><h2>Conta e sincronização</h2><span class="badge ${neonOnline?'':'orange'}">${esc(sessionLabel)}</span></div><p class="subtext">Sessão atual: <b>${esc(loginUser)}</b>. O acesso ao banco é validado pelo servidor; a senha não é gravada no aplicativo.</p><div class="settings-actions">${action('logout','Sair desta conta','','','button danger')}</div><p class="helper" style="margin-top:15px">Armazenamento local: ${storageMode==='indexeddb'?'IndexedDB':storageMode==='localStorage'?'localStorage':'indisponível'}. Se a internet cair, o aplicativo mantém a cópia local e sincroniza novamente quando possível.</p></section></div>`}'''
s=s[:start]+new_settings+s[end:]
old_click="if(name==='neon-connect'){$('neonToken').value='';$('neonDialog').showModal();setTimeout(()=>$('neonToken').focus(),50)}if(name==='neon-disconnect'){setNeonToken('');neonOnline=false;updateSaveStatus();render();toast('Neon desconectado neste aparelho. Seus dados locais foram mantidos.')}"
assert old_click in s
s=s.replace(old_click,"if(name==='logout'){await appLogout();toast('Sessão encerrada neste aparelho.')}",1)
s=s.replace("if(event.target.closest('.close-dialog'))$('editDialog').close();if(event.target.closest('.close-detail'))$('detailDialog').close();if(event.target.closest('.close-neon'))$('neonDialog').close();","if(event.target.closest('.close-dialog'))$('editDialog').close();if(event.target.closest('.close-detail'))$('detailDialog').close();",1)
line="$('neonForm').addEventListener('submit',async event=>{event.preventDefault();const button=$('connectNeonButton'),token=String(new FormData(event.target).get('token')||'').trim();button.disabled=true;try{await connectNeon(token,{firstConnection:true});$('neonDialog').close()}catch(e){toast(e.message||'Não foi possível conectar ao Neon. Confira a chave.')}finally{button.disabled=false}});"
assert line in s
login_listener=r'''$('loginForm').addEventListener('submit',async event=>{event.preventDefault();const button=$('loginButton'),data=new FormData(event.target),username=String(data.get('username')||'').trim(),password=String(data.get('password')||'');if(!username||!password)return;button.disabled=true;button.textContent='Entrando…';$('loginError').textContent='';try{await appLogin(username,password);toast('Acesso liberado. Bem-vindo ao Florindo Sistemas.')}catch(e){setNeonToken('');neonOnline=false;const unauthorized=e.status===401||e.status===403||String(e.message).includes('invalid_credentials')||String(e.message).toLowerCase().includes('unauthorized');showLogin(unauthorized?'Usuário ou senha incorretos.':'Não foi possível entrar. Verifique sua internet e tente novamente.')}finally{button.disabled=false;button.textContent='Entrar'}});'''
s=s.replace(line,login_listener,1)
old_start="async function start(){await initStorage();route=nav.some(x=>x[0]===location.hash.slice(1))?location.hash.slice(1):'overview';render();if(!neonToken())setTimeout(()=>{if(!$('neonDialog').open)$('neonDialog').showModal()},250)}"
assert old_start in s
new_start="async function start(){await initStorage();route=nav.some(x=>x[0]===location.hash.slice(1))?location.hash.slice(1):'overview';render();const logo=document.querySelector('.brand-logo');if(logo&&$('loginLogo'))$('loginLogo').src=logo.src;const token=neonToken();if(token){try{await connectNeon(token);hideLogin()}catch(e){setNeonToken('');neonOnline=false;showLogin('Sua sessão expirou. Entre novamente.')}}else showLogin()}"
s=s.replace(old_start,new_start,1)
s=re.sub(r'<dialog id="neonDialog">.*?</dialog>\n','',s,count=1,flags=re.S)
for must in ['id="loginForm"','florindo_login','appLogout','Sua sessão expirou','env(safe-area-inset-top)']: assert must in s,must
assert 'id="neonDialog"' not in s
p.write_text(s,encoding='utf-8')
print(f'Login e safe-area aplicados em {p} ({len(s)} bytes)')